{
  "appName": "SalonBooker",
  "appType": "booking",
  "summary": "A booking app for a hair salon where customers can book appointments with stylists for services, staff can manage the schedule, and a premium feature unlocks SMS reminders.",
  "entities": [
    {
      "name": "customer",
      "fields": ["name", "contactInfo"]
    },
    {
      "name": "stylist",
      "fields": ["name", "specialty"]
    },
    {
      "name": "service",
      "fields": ["name", "duration", "price"]
    },
    {
      "name": "appointment",
      "fields": ["customer", "stylist", "service", "dateTime", "status"]
    }
  ],
  "roles": [
    "customer",
    "stylist",
    "admin"
  ],
  "features": [
    "auth",
    "scheduling",
    "serviceManagement",
    "staffManagement",
    "payments",
    "smsReminders"
  ],
  "hasAuth": true,
  "hasPayments": true,
  "ambiguities": [],
  "assumptions": [
    "The app will handle user authentication for customers, stylists, and administrators.",
    "Payments will be processed for services booked.",
    "SMS reminders are a premium feature that requires a subscription or one-time purchase.",
    "Staff roles will include stylists and potentially salon administrators."
  ],
  "clarifyingQuestions": []
}
